-- Simplified Chinese translations of the English opening stories (machine-assisted).
ns.OriginStories["zh"] = {}
ns.OriginStories["zh"]["Human:WARRIOR"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为战士，你将训练化为守护，为城市难以捍卫的村庄与道路提供庇护。"
ns.OriginStories["zh"]["Human:PALADIN"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为圣骑士，你将武器与光明结合，为依赖暴风城庇护的人们延续希望。"
ns.OriginStories["zh"]["Human:HUNTER"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为猎人，你深知人类聚居地与荒野的界限，觅食也意味着直面危险。"
ns.OriginStories["zh"]["Human:ROGUE"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为潜行者，你能在城门后发现威胁，于巡逻无法涉足之处采取行动。"
ns.OriginStories["zh"]["Human:PRIEST"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为牧师，你的精神之力可疗愈一个需要超越士兵之力才能复苏的社群。"
ns.OriginStories["zh"]["Human:SHAMAN"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为萨满祭司，你倾听元素之声，回应人类冲突对周遭世界的扰动。"
ns.OriginStories["zh"]["Human:MAGE"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为法师，你将奥术研究转化为守护王国的手段，见证魔法的代价与价值。"
ns.OriginStories["zh"]["Human:WARLOCK"] = "暴风城庇护着一个因战争与家园脆弱而塑造的民族。作为术士，你探索社会所不信任的力量：助益族人不等于消除使用恶魔之力的风险。"
ns.OriginStories["zh"]["Human:DRUID"] = "暴风城庇护着一群在战火中成长、家园脆弱的人民。作为德鲁伊，你对生命的感知让你将目光投向那些支撑人类居所的森林与田野。"
ns.OriginStories["zh"]["Dwarf:WARRIOR"] = "在卡兹莫丹的群山中，铁炉堡的矮人守护家园，同时追寻过去的真相。作为战士，你的纪律延续着族人捍卫厅堂与盟友的坚定意志。"
ns.OriginStories["zh"]["Dwarf:PALADIN"] = "在卡兹莫丹的群山中，铁炉堡的矮人守护家园，同时追寻过去的真相。作为圣骑士，你将族人的坚韧与光之力量结合，守护比石墙更持久的事物。"
ns.OriginStories["zh"]["Dwarf:HUNTER"] = "在卡兹莫丹的群山中，铁炉堡的矮人守护家园，同时追寻过去的真相。作为猎人，你对山川的熟悉能为矮人社群的通道带来安全。"
ns.OriginStories["zh"]["Dwarf:ROGUE"] = "在卡兹莫丹的群山中，铁炉堡的矮人守护家园，同时追寻过去的真相。作为潜行者，你找寻路径与秘密的能力，在废墟、远征与隐秘威胁的世界中至关重要。"
ns.OriginStories["zh"]["Dwarf:PRIEST"] = "在卡兹莫丹的群山中，铁炉堡的矮人守护家园，同时追寻过去的真相。作为牧师，你为面对群山险峻与深渊威胁的人们提供照料与精神指引。"
ns.OriginStories["zh"]["Dwarf:SHAMAN"] = "在卡兹莫丹的群山中，铁炉堡的矮人守护家园，同时追寻过去的真相。作为萨满祭司，你与大地与元素的联结，为你族挖掘与研究的世界提供另一种聆听方式。"
ns.OriginStories["zh"]["Dwarf:MAGE"] = "在卡兹莫丹的群山中，铁炉堡的矮人守护家园，同时追寻过去的真相。作为法师，你将神秘学识融入矮人的求知欲，铭记古老遗物既可能揭示真相，亦可能埋藏危险。"
ns.OriginStories["zh"]["Dwarf:WARLOCK"] = "在卡兹莫丹的群山之间，铁炉堡的矮人守护家园，同时追寻过往的真相。作为术士，你对力量的追寻，将你引向那些连岩石与固执都无法束缚的力量。"
ns.OriginStories["zh"]["Dwarf:DRUID"] = "在卡兹莫丹的群山之间，铁炉堡的矮人守护家园，同时追寻过往的真相。作为德鲁伊，你誓要守护山川的生机，并铭记这片土地也属于其他生灵。"
ns.OriginStories["zh"]["Gnome:WARRIOR"] = "诺莫瑞根的沦陷迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为战士，你证明了你们的防御不仅依赖机器，更仰仗纪律与勇气。"
ns.OriginStories["zh"]["Gnome:PALADIN"] = "诺莫瑞根的沦陷迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为圣骑士，你的信仰与训练，为流离失所的族群带来庇护与希望。"
ns.OriginStories["zh"]["Gnome:HUNTER"] = "诺莫瑞根的沦陷迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为猎人，你从一个不似机器般运作的世界中学习，或许这片土地正为你们敞开新的家园。"
ns.OriginStories["zh"]["Gnome:ROGUE"] = "诺莫瑞根的沦陷迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为潜行者，你的谨慎与精准，助你穿越那些蛮力无法化解的险境。"
ns.OriginStories["zh"]["Gnome:PRIEST"] = "诺莫瑞根的沦陷迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为牧师，你照料着失去家园的人民，为他们抚平伤痛，重燃对未来的信心。"
ns.OriginStories["zh"]["Gnome:SHAMAN"] = "诺莫瑞根的沦陷迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为萨满祭司，倾听自然之力，让你与那些无法仅凭图纸与机械理解的力量产生共鸣。"
ns.OriginStories["zh"]["Gnome:MAGE"] = "诺莫瑞根的陷落迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为法师，你的好奇心将转向奥术领域，实验既需要控制，也需要想象力。"
ns.OriginStories["zh"]["Gnome:WARLOCK"] = "诺莫瑞根的陷落迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为术士，你将好奇转向恶魔之力，其代价远非机械零件可比。"
ns.OriginStories["zh"]["Gnome:DRUID"] = "诺莫瑞根的陷落迫使侏儒们投靠矮人盟友。重建未来需要智慧与毅力。作为德鲁伊，你寻求与生命的联结，这既呼应族人的智慧，也为未来提供想象空间。"
ns.OriginStories["zh"]["NightElf:WARRIOR"] = "千年来，暗夜精灵与艾露恩、森林共生，如今战争已将世界拓展至边界之外。作为战士，你的训练将守护那些森林与生灵，当旧日圣地不再安全。"
ns.OriginStories["zh"]["NightElf:PALADIN"] = "千年来，暗夜精灵与艾露恩、森林共生，如今战争已将世界拓展至边界之外。作为圣骑士，你与光的联结，承载着守护一个在变局中寻找方向的族群的责任。"
ns.OriginStories["zh"]["NightElf:HUNTER"] = "千年来，暗夜精灵与艾露恩、森林共生，如今战争已将世界拓展至边界之外。作为猎人，你理解野兽与森林的羁绊：守护族人，意味着理解滋养他们的土地。"
ns.OriginStories["zh"]["NightElf:ROGUE"] = "千年来，暗夜精灵与艾露恩、森林共生，如今战争已将世界拓展至边界之外。作为潜行者，你以隐匿揭开阴影中的威胁，那些森林同样庇护着暗夜精灵。"
ns.OriginStories["zh"]["NightElf:PRIEST"] = "千年来，暗夜精灵与艾露恩、森林共生，如今战争已将世界拓展至边界之外。作为牧师，你的精神之路在族人的信仰与治愈战争留下的创伤之间展开。"
ns.OriginStories["zh"]["NightElf:SHAMAN"] = "千年岁月，暗夜精灵与艾露恩、森林共生共存。如今战火将世界推向他们边界之外，他们必须适应这全新的现实。作为萨满，你倾听森林的元素，维系生命、灵体与世界之力的平衡。"
ns.OriginStories["zh"]["NightElf:MAGE"] = "千年岁月，暗夜精灵与艾露恩、森林共生共存。如今战火将世界推向他们边界之外，他们必须适应这全新的现实。作为法师，你研究一种深植于暗夜精灵记忆中的力量，掌控它需理解其价值与代价。"
ns.OriginStories["zh"]["NightElf:WARLOCK"] = "千年岁月，暗夜精灵与艾露恩、森林共生共存。如今战火将世界推向他们边界之外，他们必须适应这全新的现实。作为术士，你汲取与暗夜精灵历史伤痕相连的恶魔之力，谨慎是学习掌控它的必修课。"
ns.OriginStories["zh"]["NightElf:DRUID"] = "千年岁月，暗夜精灵与艾露恩、森林共生共存。如今战火将世界推向他们边界之外，他们必须适应这全新的现实。作为德鲁伊，守护自然的平衡，即是维系森林与族人的存续之道。"
ns.OriginStories["zh"]["Orc:WARRIOR"] = "历经燃烧军团的奴役，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统的荣光。作为战士，你的力量因守护新生部落与抉择值得战斗之事而获得意义。"
ns.OriginStories["zh"]["Orc:PALADIN"] = "历经燃烧军团的奴役，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统的荣光。作为圣骑士，光明与武艺的纪律，为挣脱恶魔枷锁的族群指引守护之路。"
ns.OriginStories["zh"]["Orc:HUNTER"] = "历经燃烧军团的奴役，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统的荣光。作为猎人，你与野兽与土地的羁绊，助族群安顿新生，不忘生存的血脉。"
ns.OriginStories["zh"]["Orc:ROGUE"] = "历经燃烧军团的奴役，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统的荣光。作为潜行者，情报与隐匿让你在正面冲突之外，守护族群的利益。"
ns.OriginStories["zh"]["Orc:PRIEST"] = "在燃烧军团的统治下苦熬许久，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统荣光。作为牧师，你的精神之力可助人疗愈腐败留下的伤痕。"
ns.OriginStories["zh"]["Orc:SHAMAN"] = "在燃烧军团的统治下苦熬许久，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统荣光。作为萨满，倾听元素之力，可重建被恶魔腐化所破坏的精神纽带。"
ns.OriginStories["zh"]["Orc:MAGE"] = "在燃烧军团的统治下苦熬许久，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统荣光。作为法师，你以奥术纪律赋予知识，让人民掌握自主意志而非盲目追逐力量。"
ns.OriginStories["zh"]["Orc:WARLOCK"] = "在燃烧军团的统治下苦熬许久，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统荣光。作为术士，你与族群衰落的黑暗力量为伍；掌控它们，并不能抹去那段历史与潜在的危险。"
ns.OriginStories["zh"]["Orc:DRUID"] = "在燃烧军团的统治下苦熬许久，兽人渴望在艾泽拉斯开创属于自己的未来，重拾传统荣光。作为德鲁伊，你与生命的联结，为新部落扎根的土地提供守护之道。"
ns.OriginStories["zh"]["Tauren:WARRIOR"] = "牛头人敬奉大地之母与祖先。他们在部落中的地位，源于守护家园与与自然共存的信念。作为战士，你所培养的力量，既护佑族群，也尊重周遭生命。"
ns.OriginStories["zh"]["Tauren:PALADIN"] = "牛头人敬奉大地之母与祖先。他们在部落中的地位，源于守护家园与与自然共存的信念。作为圣骑士，你将光明之力与训练结合，为族人提供庇护。"
ns.OriginStories["zh"]["Tauren:HUNTER"] = "牛头人敬奉大地之母与祖先。他们在部落中的地位，源于守护家园与与自然共存的信念。作为猎人，你深知取用自然，亦需懂得并尊重维系族群的根基。"
ns.OriginStories["zh"]["Tauren:ROGUE"] = "巨魔敬奉大地之母与祖先。他们在部落中的地位源于守护家园与与自然共存。作为潜行者，观察与谨慎让你能在危机触及家园前预见危险。"
ns.OriginStories["zh"]["Tauren:PRIEST"] = "巨魔敬奉大地之母与祖先。他们在部落中的地位源于守护家园与与自然共存。作为牧师，你的灵性修习融入了这个以记忆、关怀与土地联结为意义的文化。"
ns.OriginStories["zh"]["Tauren:SHAMAN"] = "巨魔敬奉大地之母与祖先。他们在部落中的地位源于守护家园与与自然共存。作为萨满，倾听元素与灵体，使你族人对平衡的追寻成为你个人的责任。"
ns.OriginStories["zh"]["Tauren:MAGE"] = "巨魔敬,敬奉大地之母与祖先。他们在部落中的地位源于守护家园与与自然共存。作为法师，对奥术的研习提供了另一条理解世界之力的路径，同时你仍需为行动对社群的影响负责。"
ns.OriginStories["zh"]["Tauren:WARLOCK"] = "巨魔敬奉大地之母与祖先。他们在部落中的地位源于守护家园与与自然共存。作为术士，恶魔之力与巨魔对平衡的追求形成张力；守护族人意味着正视危险的存在。"
ns.OriginStories["zh"]["Tauren:DRUID"] = "巨魔敬奉大地之母与祖先。他们在部落中的地位源于守护家园与与自然共存。作为德鲁伊，向动物学习并化为它们的形态，体现了你族人与大地之母活生生世界之间的纽带。"
ns.OriginStories["zh"]["Troll:WARRIOR"] = "黑暗之矛在部落中找到盟友以度过流放。他们的传统与对洛阿的信仰伴随了守护家园的斗争。作为战士，你的武器技艺助你捍卫家园与族人追求的独立。"
ns.OriginStories["zh"]["Troll:PALADIN"] = "黑暗之矛在部落中找到盟友以度过流放。他们的传统与对洛阿的信仰伴随了守护家园的斗争。作为圣骑士，你与光的联结为一个生存依赖关系的社群提供庇护。"
ns.OriginStories["zh"]["Troll:HUNTER"] = "黑暗之矛在部落中找到盟友，方能熬过流放之痛。他们的传统与对洛阿的信仰，伴随他们为家园而战的历程。作为猎人，你对野兽与险地的了解，能助黑暗之矛抵御新的威胁。"
ns.OriginStories["zh"]["Troll:ROGUE"] = "黑暗之矛在部落中找到盟友，方能熬过流放之痛。他们的传统与对洛阿的信仰，伴随他们为家园而战的历程。作为潜行者，你的隐匿与情报，能助熟悉危险的族群先敌一步。"
ns.OriginStories["zh"]["Troll:PRIEST"] = "黑暗之矛在部落中找到盟友，方能熬过流放之痛。他们的传统与对洛阿的信仰，伴随他们为家园而战的历程。作为牧师，你的精神之路，介于族人的传统与疗愈、守护、理解心灵的需要之间。"
ns.OriginStories["zh"]["Troll:SHAMAN"] = "黑暗之矛在部落中找到盟友，方能熬过流放之痛。他们的传统与对洛阿的信仰，伴随他们为家园而战的历程。作为萨满祭司，你与元素的联系，融入一个精灵即是日常的生活。"
ns.OriginStories["zh"]["Troll:MAGE"] = "黑暗之矛在部落中找到盟友，方能熬过流放之痛。他们的传统与对洛阿的信仰，伴随他们为家园而战的历程。作为法师，你学会驾驭奥术之力，当知识与力量同样重要时，这力量可为族人所用。"
ns.OriginStories["zh"]["Troll:WARLOCK"] = "黑暗之矛在部落中找到盟友，方能熬过流放之痛。他们的传统与对洛阿的信仰，伴随他们为家园而战的历程。作为术士，你从洛阿之外的恶魔力量汲取力量。学会驾驭它们，意味着正视它们对你与所保护之人的威胁。"
ns.OriginStories["zh"]["Troll:DRUID"] = "黑暗之矛在部落中找到盟友，方能熬过流放之痛。他们的传统与对洛阿的信仰，伴随他们为家园而战的历程。作为德鲁伊，你与动物与自然的羁绊，为族人赖以生存的土地提供另一种守护方式。"
ns.OriginStories["zh"]["Scourge:WARRIOR"] = "你已在仍惧怕你的世界中苏醒。被遗忘者挣脱天灾军团的控制，重获自由意志，如今在洛丹伦的废墟中寻求属于自己的存在。作为战士，你的训练让你能以武器捍卫这份自由——你不再为他人之命而战。"
ns.OriginStories["zh"]["Scourge:PALADIN"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为圣骑士，你手握的光明来自一个被许多人视为与之不兼容的存在。你的信仰与训练，助你守护这些重获自由的亡灵。"
ns.OriginStories["zh"]["Scourge:HUNTER"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为猎人，学会与野兽与环境建立联系，是你在这样一个不信任你的世界中找到立足之地的关键。"
ns.OriginStories["zh"]["Scourge:ROGUE"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为潜行者，隐匿与精准是你在这样一个公开露面可能致命的国度中，保护族人的手段。"
ns.OriginStories["zh"]["Scourge:PRIEST"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为牧师，你与光明与黑暗的关系，有了更深的意味：你试图理解并驾驭一种挑战生者确定性的存在所赋予的精神力量。"
ns.OriginStories["zh"]["Scourge:SHAMAN"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为萨满，你试图聆听元素的低语，而这一切来自一个超出生命常态循环的存在，你不会让这决定你如何使用自由。"
ns.OriginStories["zh"]["Scourge:MAGE"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为法师，奥术的纪律能助你守护独立，理解一种死亡也未能抹去的存在。"
ns.OriginStories["zh"]["Scourge:WARLOCK"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为术士，你重获的自由更让你必须区分：掌控危险的力量，与再次臣服于另一个意志之间，究竟何者更为重要。"
ns.OriginStories["zh"]["Scourge:DRUID"] = "你已在一片仍对你心存恐惧的世界中苏醒。被遗忘者挣脱了天灾军团的控制，如今在洛丹伦的废墟中追寻属于自己的存在。身为德鲁伊，你与自然的羁绊，引发了对生死的疑问；你新得的自由，让你得以追寻自己的答案。"
ns.OriginStories["zh"]["Skyborne:Alliance:WARRIOR"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为战士，你的纪律能守护那些需要时间与安全寻找出路的子民。"
ns.OriginStories["zh"]["Skyborne:Alliance:PALADIN"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为圣骑士，你以光与武器凝聚力量，捍卫一个未来不再安稳的社群。"
ns.OriginStories["zh"]["Skyborne:Alliance:HUNTER"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为猎人，观察生物与环境能让你洞悉这场危机如何波及邻近的生命。"
ns.OriginStories["zh"]["Skyborne:Alliance:ROGUE"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为潜行者，情报与隐秘的路径能为你在旧日庇护所不再足够时，开辟新的可能。"
ns.OriginStories["zh"]["Skyborne:Alliance:PRIEST"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为牧师，你支撑着一个失去确定性的社群，为他们寻找继续前行的新理由。"
ns.OriginStories["zh"]["Skyborne:Alliance:SHAMAN"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为萨满祭司，你与元素的羁绊让一个核心问题悬而未决：那些维系泽弗拉斯的灵体究竟去了哪里？"
ns.OriginStories["zh"]["Skyborne:Alliance:MAGE"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为法师，你的奥术研究直接指向玄夜会的目标：理解一个可能为族人提供新出路的遗产。"
ns.OriginStories["zh"]["Skyborne:Alliance:WARLOCK"] = "泽弗拉斯的晨露族正面对风灵消逝的危机，这些灵体曾维系着他们的家园。玄夜会追寻远古的奥术知识，将未来更紧密地联结至联盟。作为术士，你寻求超越泽弗拉斯失去确定性的力量，但转向恶魔并不能消除这场危机的危险。"
ns.OriginStories["zh"]["Skyborne:Alliance:DRUID"] = "泽弗拉斯的风灵消失，威胁着这片维系家园的自然之力。高等秩序追寻远古奥术知识，将未来与联盟拉得更近。作为德鲁伊，你需守护依赖泽弗拉斯的生命，探寻如何重建与周遭力量的可持续联系。"
ns.OriginStories["zh"]["Skyborne:Horde:WARRIOR"] = "风灵的消失威胁着泽弗拉斯，这片风灵栖息的家园。风塑者通过元素传统追寻答案，找到通往部落的道路。作为战士，你的训练可守护那些努力恢复家园稳定的人们。"
ns.OriginStories["zh"]["Skyborne:Horde:PALADIN"] = "风灵的消失威胁着泽弗拉斯，这片风灵栖息的家园。风塑者通过元素传统追寻答案，找到通往部落的道路。作为圣骑士，你的守护之力支撑着一个需要希望的社区，而它与世界的联系正在改变。"
ns.OriginStories["zh"]["Skyborne:Horde:HUNTER"] = "风灵的消失威胁着泽弗拉斯，这片风灵栖息的家园。风塑者通过元素传统追寻答案，找到通往部落的道路。作为猎人，你对野生动物的了解，能让你看清泽弗拉斯的危机如何影响族群的生灵与资源。"
ns.OriginStories["zh"]["Skyborne:Horde:ROGUE"] = "风灵的消失威胁着泽弗拉斯，这片风灵栖息的家园。风塑者通过元素传统追寻答案，找到通往部落的道路。作为潜行者，你的隐匿与情报助你把握机会、预判威胁，而你的族群正努力守护未来。"
ns.OriginStories["zh"]["Skyborne:Horde:PRIEST"] = "风灵的消失威胁着泽弗拉斯，这片风灵栖息的家园。风塑者通过元素传统追寻答案，找到通往部落的道路。作为牧师，你的精神之路可帮助一个失去灵体陪伴的社区维系生存。"
ns.OriginStories["zh"]["Skyborne:Horde:SHAMAN"] = "风灵的消失威胁着泽弗拉斯，这片风灵栖息的家园。风塑者通过元素传统追寻答案，找到通往部落的道路。作为萨满祭司，你的元素纽带直接连接着风塑者的探索：理解灵体的缺席，为泽弗拉斯寻找未来。"
ns.OriginStories["zh"]["Skyborne:Horde:MAGE"] = "风灵的消失威胁着泽弗拉斯，这片风灵栖息的家园。风塑者通过元素传统追寻答案，找到通往部落的道路。作为法师，你的奥术专精为理解危机提供了另一把钥匙，却不取代族群的元素传统。"
ns.OriginStories["zh"]["Skyborne:Horde:WARLOCK"] = "清风之魂的消逝危及泽弗拉斯——这片慎多瑞的家园。风塑者借元素传统追寻真相，踏上通往部落之路。身为术士，你向危险之力寻求资源；拯救家园的渴望，也未必能换取恶魔之力的盟约，代价从未缺席。"
ns.OriginStories["zh"]["Skyborne:Horde:DRUID"] = "清风之魂的消逝危及泽弗拉斯——这片慎多瑞的家园。风塑者借元素传统追寻真相，踏上通往部落之路。身为德鲁伊，你誓守护这片土地的生机，探寻无需清风之魂便能维系的平衡。"
